% mathsmap-diagram-colours {"version":1,"kind":"graph","base":[],"semantic":[],"reference":"source page 3 question 2; teacher page 43 question 2a"}
\begin{tikzpicture}[x=0.9cm,y=0.9cm,line cap=round,line join=round]
\special{dvisvgm:raw <metadata data-graph-strokes="1"/>}
\path[use as bounding box] (-4.5,-5.4) rectangle (5.8,6.2);
\draw[step=1,line width=0.25pt,black!20] (-2,-2) grid (5,5);
\draw[->,line width=0.5pt,black] (-2.2,0)--(5.5,0) node[right] {$x$};
\draw[->,line width=0.5pt,black] (0,-2.2)--(0,5.6) node[above] {$y$};
\foreach \v in {-2,-1,1,2,3,4,5} {
\draw[line width=0.4pt] (\v,0.07)--(\v,-0.07) node[below] {\special{dvisvgm:raw <g data-graph-text="tick">}$\v$\special{dvisvgm:raw </g>}};
\draw[line width=0.4pt] (0.07,\v)--(-0.07,\v) node[left] {\special{dvisvgm:raw <g data-graph-text="tick">}$\v$\special{dvisvgm:raw </g>}};
}
\draw[line width=0.8pt,black,domain=-2:5] plot (\x,\x);
\draw[line width=0.8pt,black,dashed,domain=-1.5:2] plot (\x,{2*\x+1});
\draw[line width=0.8pt,black,dash dot,domain=-1:5] plot (\x,{4-\x});
\node[anchor=west] at (-2,-3.2) {$\text{solid: }y=x$};
\node[anchor=west] at (-2,-4) {$\text{dashed: }y=2x+1$};
\node[anchor=west] at (-2,-4.8) {$\text{dash dot: }x+y=4$};
\fill[black] (-1,-1) circle (1.7pt);
\draw[line width=0.4pt] (-1,-1)--(-4,-1);
\node[anchor=east] at (-4,-1) {$(-1,-1)$};
\fill[black] (2,2) circle (1.7pt);
\draw[line width=0.4pt] (2,2)--(0,1.5)--(-4,1.5);
\node[anchor=east] at (-4,1.5) {$(2,2)$};
\fill[black] (1,3) circle (1.7pt);
\draw[line width=0.4pt] (1,3)--(-4,4.2);
\node[anchor=east] at (-4,4.2) {$(1,3)$};
\end{tikzpicture}
